import React from 'react';

export function Pagination({ total, page = 1 }: { total: number; page?: number }) {
  const [current, setCurrent] = React.useState(page);
  const pages = Array.from({ length: Math.min(total, 7) }, (_, i) => i + 1);
  const go = (p: number) => { if (p >= 1 && p <= total) setCurrent(p); };
  return (
    <nav aria-label="Pagination" style={{ display: 'flex', alignItems: 'center', gap: '4px' }}>
      <button aria-label="Previous page" disabled={current <= 1} onClick={() => go(current - 1)} style={pageBtn(true)}>‹</button>
      {pages.map((p) => (
        <button key={p} aria-current={p === current ? 'page' : undefined} aria-label={`Page ${p}`} onClick={() => go(p)}
          style={{ ...pageBtn(p === current), background: p === current ? '{{token:colors.accent.primary}}' : '{{token:colors.base.surface}}', color: p === current ? '{{token:colors.text.inverse}}' : '{{token:colors.text.primary}}', border: '1px solid {{token:colors.base.border}}' }}>{p}</button>
      ))}
      <button aria-label="Next page" disabled={current >= total} onClick={() => go(current + 1)} style={pageBtn(true)}>›</button>
    </nav>
  );
  function pageBtn(active: boolean) {
    return { minWidth: '32px', height: '32px', borderRadius: '{{token:spacing.card.borderRadius}}', border: 'none', cursor: active ? 'pointer' : 'not-allowed', opacity: active ? 1 : 0.5, fontSize: '{{token:typography.scale.sm}}' };
  }
}
